def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001
        return num + 2  # e.g. 9->11, 99->101, 999->1001, all are num+2

    def make_palindrome(left: str, middle: str, length: int) -> int:
        if length % 2 == 0:
            return int(left + left[::-1])
        else:
            return int(left + middle + left[::-1])

    half_len = length // 2
    if length % 2 == 0:
        left = s[:half_len]
        middle = ''
        palindrome = make_palindrome(left, middle, length)
        if palindrome > num:
            return palindrome
        # increment left and mirror again
        left_int = int(left) + 1
        left = str(left_int)
        if len(left) > half_len:
            # overflow, e.g. 99 -> 100, palindrome length increases
            return int('1' + ('0' * (length -1)) + '1')
        return make_palindrome(left, middle, length)
    else:
        left = s[:half_len]
        middle = s[half_len]
        palindrome = make_palindrome(left, middle, length)
        if palindrome > num:
            return palindrome
        # increment middle+left as one number
        left_middle_int = int(left + middle) + 1
        left_middle_str = str(left_middle_int)
        if len(left_middle_str) > half_len + 1:
            # overflow, e.g. 999 -> 1000, palindrome length increases
            return int('1' + ('0' * (length -1)) + '1')
        left = left_middle_str[:-1]
        middle = left_middle_str[-1]
        return make_palindrome(left, middle, length)

