import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # cannot reach any non-zero point with zero-length moves
    # If one jump can exactly reach (d,0)
    if d == length:
        return 1
    # If one jump is longer than d, but cannot land exactly at (d,0), two jumps suffice:
    # because you can jump length in any direction, two jumps can reach any point within 
    # radius up to 2*length, including all points between 0 and 2*length.
    if length > d:
        return 2

    # Otherwise, need enough jumps so that total length >= d
    return math.ceil(d / length)

