def anti_shuffle(s):
    def sort_word(word):
        # Separate leading and trailing spaces (none needed here as split preserves spaces)
        # Sort letters only, keep punctuation in place
        # But per clarification, word includes letters and punctuation together.
        # So we sort all characters in the word and return the sorted string.
        return ''.join(sorted(word))

    # We need to keep all spaces as is, including multiple spaces between words.
    # So we split by spaces, but keep the spaces in result.
    # Using str.split(' ') splits on single space but removes consecutive spaces.
    # Instead, we can split with regex to keep spaces.
    import re
    tokens = re.findall(r'\S+|\s+', s)
    # tokens will be either sequences of non-space chars (words) or sequences of spaces

    result = []
    for token in tokens:
        if token.isspace():
            # keep spaces as is
            result.append(token)
        else:
            # sort the token characters
            result.append(sort_word(token))
    return ''.join(result)

